class Adder {
    int sum;
public:
    Adder() : sum(0) {}
    void operator()(int x) { sum += x; }
    int getSum() const { return sum; }
};

class CompareByAbs {
public:
    bool operator()(int a, int b) const { return abs(a) < abs(b); }
};

int main() {
    vector<int> v = {3, 1, 4, 1, 5, 9};
    sort(v.begin(), v.end(), greater<int>());

    vector<int> nums = {-5, 2, -3, 1, -4};
    sort(nums.begin(), nums.end(), CompareByAbs());

    vector<int> arr = {1, 2, 3, 4, 5};
    Adder adder = for_each(arr.begin(), arr.end(), Adder());
    cout << "Sum: " << adder.getSum() << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> buildNext(const string& pattern) {
    int m = pattern.size();
    vector<int> next(m, 0);
    int len = 0, i = 1;
    while (i < m) {
        if (pattern[i] == pattern[len]) { len++; next[i] = len; i++; }
        else { if (len != 0) len = next[len - 1]; else { next[i] = 0; i++; } }
    }
    return next;
}

int kmpSearch(const string& text, const string& pattern) {
    int n = text.size(), m = pattern.size();
    if (m == 0) return 0;
    vector<int> next = buildNext(pattern);
    int i = 0, j = 0;
    while (i < n) {
        if (text[i] == pattern[j]) { i++; j++; if (j == m) return i - j; }
        else { if (j != 0) j = next[j - 1]; else i++; }
    }
    return -1;
}

int main() {
    string text = "ABABDABACDABABCABAB";
    string pattern = "ABABCABAB";
    cout << "Found at: " << kmpSearch(text, pattern) << endl;
    return 0;
}

