using namespace std;

struct Edge { int u, v, weight; bool operator<(const Edge& o) const { return weight < o.weight; } };

class UnionFind {
    vector<int> parent, rank;
public:
    UnionFind(int n) : parent(n), rank(n, 0) { for (int i = 0; i < n; i++) parent[i] = i; }
    int find(int x) { if (parent[x] != x) parent[x] = find(parent[x]); return parent[x]; }
    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) swap(px, py);
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }
};

vector<Edge> kruskal(int n, vector<Edge>& edges) {
    sort(edges.begin(), edges.end());
    UnionFind uf(n);
    vector<Edge> mst;
    for (Edge& e : edges) {
        if (uf.unite(e.u, e.v)) { mst.push_back(e); if (mst.size() == n - 1) break; }
    }
    return mst;
}

#include <iostream>
#include <atomic>
#include <thread>
using namespace std;

atomic<bool> ready{false};
atomic<int> data{0};

void producer() {
    data.store(42, memory_order_relaxed);
    ready.store(true, memory_order_release);
}

void consumer() {
    while (!ready.load(memory_order_acquire));
    cout << "Data: " << data.load(memory_order_relaxed) << endl;
}

int main() {
    thread t1(producer), t2(consumer);
    t1.join(); t2.join();

    atomic<int> counter{0};
    counter.fetch_add(1, memory_order_relaxed);

    atomic<int> value{0};
    int expected = 0;
    value.compare_exchange_weak(expected, 1);
    return 0;
}

