int countBits(int n) {
    int count = 0;
    while (n) { n &= n - 1; count++; }
    return count;
}

bool isPowerOfTwo(int n) { return n > 0 && (n & (n - 1)) == 0; }

int getBit(int n, int k) { return (n >> k) & 1; }
int setBit(int n, int k) { return n | (1 << k); }
int clearBit(int n, int k) { return n & ~(1 << k); }
int toggleBit(int n, int k) { return n ^ (1 << k); }

int add(int a, int b) {
    while (b != 0) {
        int carry = a & b;
        a = a ^ b;
        b = carry << 1;
    }
    return a;
}

