#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
using namespace std;

template<typename T>
class ThreadSafeQueue {
    queue<T> queue;
    mutable mutex mut;
    condition_variable dataCond;
public:
    void push(T value) {
        lock_guard<mutex> lock(mut);
        queue.push(move(value));
        dataCond.notify_one();
    }
    void pop(T& value) {
        unique_lock<mutex> lock(mut);
        dataCond.wait(lock, [this] { return !queue.empty(); });
        value = move(queue.front());
        queue.pop();
    }
};

int main() {
    ThreadSafeQueue<int> q;
    thread t1([&q] { for (int i = 0; i < 5; i++) q.push(i); });
    thread t2([&q] { for (int i = 0; i < 5; i++) { int v; q.pop(v); cout << v << " "; } });
    t1.join(); t2.join();

    atomic<int> counter{0};
    counter.fetch_add(1);
    return 0;
}

#include <iostream>
#include <coroutine>
using namespace std;

template<typename T>
struct Generator {
    struct promise_type {
        Generator get_return_object() { return Generator{Handle::from_promise(*this)}; }
        suspend_always initial_suspend() { return {}; }
        suspend_always final_suspend() noexcept { return {}; }
        suspend_always yield_value(T value) { current_value = value; return {}; }
        void return_void() {}
        void unhandled_exception() { exit(1); }
        T current_value;
    };
    using Handle = coroutine_handle<promise_type>;
    Handle handle;
    Generator(Handle h) : handle(h) {}
    ~Generator() { if (handle) handle.destroy(); }
    Generator(Generator&& o) noexcept : handle(o.handle) { o.handle = nullptr; }
    bool hasNext() const { return handle && !handle.done(); }
    T next() { handle.resume(); return handle.promise().current_value; }
};

Generator<int> fibonacci() {
    int a = 0, b = 1;
    while (true) { co_yield a; int t = a + b; a = b; b = t; }
}

int main() {
    auto fib = fibonacci();
    for (int i = 0; i < 10; i++) cout << fib.next() << " ";
    cout << endl;
    return 0;
}
